#!/usr/bin/env node
/**
 * 前端 ↔ 后端命令一致性守护（M1-S4 spec §7 / §8.2）。
 *
 * 三件事：
 * 1. `src-tauri/src/commands_list.rs` 的 `COMMANDS` 与 `src/lib/api.ts` 的
 *    `INVOKED_COMMANDS` 必须是**同一个集合**（少一个 = 有命令没人调，多一个 = 调了不存在的命令）；
 * 2. `src-tauri/capabilities/default.json` 必须为每条命令声明 `allow-<kebab-case>`；
 * 3. **只有** `src/lib/api.ts` 允许 `import("@tauri-apps/api")`，页面组件必须走 api 层。
 * 4. `src-tauri/permissions/autogenerated/` 的文件集合必须与 `COMMANDS` 相同（B-25：
 *    命令改名/删除后旧文件不会被 `tauri-build` 清理，幽灵文件会让 `git status` 变脏）。
 *
 * 退出码非 0 即失败，供 `pnpm test` 使用。
 */

import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));

function fail(message) {
  console.error(`✗ ${message}`);
  process.exitCode = 1;
}

function ok(message) {
  console.log(`✓ ${message}`);
}

/**
 * 去掉注释，避免把被注释掉的命令/通道也算进来（否则「删一条命令」抓不到）。
 *
 * **块注释也必须去**（M8-S5B 独立复审 P2-1）：只去行注释时，把一条 `CHANNELS`
 * 条目用 `/* … *\/` 包起来就能让前端清单少一项而脚本照旧绿——
 * 独立复审在沙箱里复现过这个「静默通过」。顺序也有讲究：**先去块注释**，
 * 否则块注释里出现的 `//` 会先把块注释切成两半，剩下的 `*\/` 变成普通文本。
 */
function stripComments(text) {
  return text
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/\/\/[^\n]*/g, "");
}

/** 从 `pub const COMMANDS: &[&str] = &[ "a", "b" ];` 里取出字符串字面量 */
function parseRustCommands() {
  const source = readFileSync(
    join(root, "src-tauri/src/commands_list.rs"),
    "utf8",
  );
  const block = source.match(/pub const COMMANDS[^=]*=\s*&\[([\s\S]*?)\];/);
  if (!block) throw new Error("在 commands_list.rs 里找不到 COMMANDS 数组");
  return [...stripComments(block[1]).matchAll(/"([^"]+)"/g)].map(
    (m) => m[1],
  );
}

/**
 * 从 `src/lib/api.ts` 里取出**真实被调用的**命令名。
 *
 * 解析的是 `invokeCommand<...>("cmd"` 这个调用点，而**不是**某个手工维护的镜像数组——
 * 镜像数组是假守护：把真实调用注释掉、数组不动，检查依然全绿
 * （M1-S3/S4 复审 P1 实测）。
 */
function parseTsCommands() {
  const source = stripComments(
    readFileSync(join(root, "src/lib/api.ts"), "utf8"),
  );
  const calls = [
    ...source.matchAll(/invokeCommand(?:<[^>]*>)?\(\s*"([a-z_]+)"/g),
  ].map((m) => m[1]);
  if (calls.length === 0) {
    throw new Error(
      "在 api.ts 里没解析到任何 invokeCommand(\"…\") 调用——解析器坏了，不能当成通过",
    );
  }
  return [...new Set(calls)];
}

/**
 * 从 `DeliveryChannel::as_str()` 的穷尽 match 里取出通道名字面量（B-101）。
 *
 * 为什么这是**可证伪**的读法：`as_str` 是穷尽 `match`，新增一个 `DeliveryChannel`
 * 变体而忘了加臂，rustc 直接报错 ⇒ 抽出来的臂数与 `ALL` 数组长度必然相等。
 * 反过来，若哪天有人把 `as_str` 改成 `#[derive]` 自动生成，这里的正则会匹配不到
 * 臂 ⇒ **宁可红，也不静默跳过**（解析器失效时报错，不当成通过）。
 */
function parseRustChannels() {
  const source = stripComments(
    readFileSync(join(root, "crates/keyrelay-core/src/delivery/mod.rs"), "utf8"),
  );
  // 只取 `as_str()` **函数体内**的臂：同一个文件里 `agent_id()` 也是同形态的 match，
  // 不限定函数就会把两份都抓进来（实测 14 条臂 vs ALL 的 7 个元素）。
  const fn = source.match(/pub fn as_str\(self\)[\s\S]*?\n    \}/);
  if (!fn) throw new Error("在 delivery/mod.rs 里找不到 as_str() 函数");
  const arms = [
    ...fn[0].matchAll(/DeliveryChannel::(\w+)\s*=>\s*"([a-z0-9-]+)"/g),
  ].map((m) => m[2]);
  if (arms.length === 0) {
    throw new Error(
      "在 delivery/mod.rs 里没解析到任何 DeliveryChannel 的 as_str 臂——解析器坏了，不能当成通过",
    );
  }
  // `ALL` 数组：与臂数对账，防「as_str 加了臂但 ALL 没加」这种半边改动
  const all = source.match(/pub const ALL[^=]*=\s*\[([\s\S]*?)\]/);
  if (!all) throw new Error("在 delivery/mod.rs 里找不到 DeliveryChannel::ALL");
  const allCount = [...all[1].matchAll(/DeliveryChannel::\w+/g)].length;
  if (allCount !== arms.length) {
    throw new Error(
      `DeliveryChannel::ALL 有 ${allCount} 个元素，但 as_str 有 ${arms.length} 条臂——两边不同步`,
    );
  }
  return arms;
}

/**
 * 从 `src/pages/Agents.tsx` 的 `CHANNELS` 数组里取出 id 字面量。
 *
 * 前端那份是**手工维护**的（界面要拿它渲染下拉），所以必须与后端对账：
 * 少了 ⇒ 用户选不到新通道；多了 ⇒ 选到一个后端不认识的通道。
 */
function parseTsChannels() {
  const source = stripComments(
    readFileSync(join(root, "src/pages/Agents.tsx"), "utf8"),
  );
  const block = source.match(/const CHANNELS\s*=\s*\[([\s\S]*?)\];/);
  if (!block) throw new Error("在 Agents.tsx 里找不到 CHANNELS 数组");
  const ids = [...block[1].matchAll(/id:\s*"([a-z0-9-]+)"/g)].map((m) => m[1]);
  if (ids.length === 0) {
    throw new Error(
      "在 Agents.tsx 的 CHANNELS 里没解析到任何 id——解析器坏了，不能当成通过",
    );
  }
  return ids;
}

/**
 * 从 `src/lib/api.ts` 的 `AGENT_CHANNELS` 表里取出 channel id 字面量（M8-S7 / B-116）。
 *
 * 为什么单独对账：这张表服务「从一条 binding 反查它属于哪条通道」
 * （`channelOfBinding`），**`CHANNELS` 的对账覆盖不到它**——两边漏一条的后果不一样：
 * `CHANNELS` 漏了用户选不到；`AGENT_CHANNELS` 漏了该行显示「无法识别通道」，
 * 用户没办法批量改指它，而**没有任何东西会红**（M8-S7 独立复审 P2-1）。
 *
 * 与 `CHANNELS` 分开断言而不是取并集：并集会让「两边都漏同一条」互相掩护。
 */
function parseTsAgentChannels() {
  const source = stripComments(
    readFileSync(join(root, "src/lib/api.ts"), "utf8"),
  );
  const block = source.match(/const AGENT_CHANNELS[^=]*=\s*\{([\s\S]*?)\n\};/);
  if (!block) throw new Error("在 api.ts 里找不到 AGENT_CHANNELS 表");
  // `Record<string, string>`：取值就是 channel id 字面量
  const ids = [...block[1].matchAll(/:\s*"([a-z0-9-]+)"/g)].map((m) => m[1]);
  if (ids.length === 0) {
    throw new Error(
      "在 api.ts 的 AGENT_CHANNELS 里没解析到任何 channel id——解析器坏了，不能当成通过",
    );
  }
  // agent 键也要与后端 `agent_id()` 的臂对账：键漏了 ⇒ 那个 agent 的绑定全查不到通道
  // `Record<string, string>`：键在行首（可能带引号），取值是字符串
  const keys = [...block[1].matchAll(/^\s{2}["']?([a-z0-9-]+)["']?:\s*"/gm)].map(
    (m) => m[1],
  );
  if (keys.length === 0) {
    throw new Error(
      "在 api.ts 的 AGENT_CHANNELS 里没解析到任何 agent 键——解析器坏了，不能当成通过",
    );
  }
  return { ids, keys };
}

/** 后端 `DeliveryChannel::agent_id()` 的臂（与 `as_str` 同形态，只是函数名不同）。 */
function parseRustAgentIds() {
  const source = stripComments(
    readFileSync(join(root, "crates/keyrelay-core/src/delivery/mod.rs"), "utf8"),
  );
  const fn = source.match(/pub fn agent_id\(self\)[\s\S]*?\n    \}/);
  if (!fn) throw new Error("在 delivery/mod.rs 里找不到 agent_id() 函数");
  const arms = [...fn[0].matchAll(/DeliveryChannel::\w+\s*=>\s*"([a-z0-9-]+)"/g)].map(
    (m) => m[1],
  );
  if (arms.length === 0) {
    throw new Error(
      "在 delivery/mod.rs 的 agent_id() 里没解析到任何臂——解析器坏了，不能当成通过",
    );
  }
  return arms;
}

function parseCapabilities() {
  const raw = readFileSync(
    join(root, "src-tauri/capabilities/default.json"),
    "utf8",
  );
  return JSON.parse(raw).permissions ?? [];
}

/** `list_sites` → `allow-list-sites`（Tauri 的权限名映射规则） */
function permissionFor(command) {
  return `allow-${command.replace(/_/g, "-")}`;
}

function walk(dir, out = []) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) walk(full, out);
    else if (/\.(ts|tsx)$/.test(entry)) out.push(full);
  }
  return out;
}

// ---------------------------------------------------------------- 1. 集合一致性

const rust = parseRustCommands();
const ts = parseTsCommands();

const onlyRust = rust.filter((c) => !ts.includes(c));
const onlyTs = ts.filter((c) => !rust.includes(c));

if (onlyRust.length) {
  fail(`后端有、前端未覆盖的命令：${onlyRust.join(", ")}`);
} else if (onlyTs.length) {
  fail(`前端调用了不存在的命令：${onlyTs.join(", ")}`);
} else {
  ok(`命令集合一致（${rust.length} 条）`);
}

// ---------------------------------------------------------------- 2. capabilities

const permissions = parseCapabilities();
const missing = rust
  .map(permissionFor)
  .filter((p) => !permissions.includes(p));

if (missing.length) {
  fail(`capabilities 缺少权限声明：${missing.join(", ")}`);
} else {
  ok(`capabilities 覆盖全部 ${rust.length} 条命令`);
}

// ---------------------------------------------------------------- 3. 唯一入口

const srcFiles = walk(join(root, "src"));
const offenders = srcFiles
  .filter((file) => relative(root, file) !== "src/lib/api.ts")
  .filter((file) => readFileSync(file, "utf8").includes("@tauri-apps/api"));

if (offenders.length) {
  fail(
    `只有 src/lib/api.ts 可以直接引用 @tauri-apps/api，违规文件：\n  ${offenders
      .map((f) => relative(root, f))
      .join("\n  ")}`,
  );
} else {
  ok("只有 src/lib/api.ts 直接引用 @tauri-apps/api");
}

// ------------------------------------------------- 4. 权限生成物 == 命令集合（B-25）

/**
 * `tauri-build` 按 `COMMANDS` 生成 `src-tauri/permissions/autogenerated/<command>.toml`。
 * 命令改名 / 删除后旧文件**不会被清理**（M1-S1 的 `zz_ghost_probe.toml` 就是这么留下的，
 * 源码恢复后它还在，`git status` 因此变脏），而「没跑过构建」又会表现为缺文件。
 * 所以两个方向都要红，并且报错必须直接指出**哪个文件 / 哪条命令**。
 */
const AUTOGENERATED_DIR = join(root, "src-tauri/permissions/autogenerated");

function listAutogeneratedFiles() {
  let entries;
  try {
    entries = readdirSync(AUTOGENERATED_DIR, { withFileTypes: true });
  } catch (error) {
    throw new Error(
      `读不到 ${relative(root, AUTOGENERATED_DIR)}/（${error.code}）。` +
        "该目录的生成物是**入库**的（B-25），缺失说明它被删了或被 .gitignore 掉了",
    );
  }
  return (
    entries
      .filter((entry) => entry.isFile())
      // macOS 的 Finder 会往目录里塞 .DS_Store；它不是权限生成物，不算幽灵
      .filter((entry) => !entry.name.startsWith("."))
      .map((entry) => entry.name)
      .sort()
  );
}

const expectedPermissionFiles = rust.map((command) => `${command}.toml`).sort();
const actualPermissionFiles = listAutogeneratedFiles();

const ghostFiles = actualPermissionFiles.filter(
  (file) => !expectedPermissionFiles.includes(file),
);
const missingFiles = expectedPermissionFiles.filter(
  (file) => !actualPermissionFiles.includes(file),
);

// 两个方向**分别**报，不写成 if/else（M5-S6 复审 P2-1）：
// 幽灵与缺失同时存在时，只报前者会让「构建没跑过 / 生成物被删」这条线索完全消失。
if (ghostFiles.length) {
  fail(
    `权限目录里有**幽灵文件**（COMMANDS 里没有对应的命令，tauri-build 不会清理）：\n  ${ghostFiles
      .map(
        (file) =>
          `${relative(root, join(AUTOGENERATED_DIR, file))}（COMMANDS 里没有「${file.replace(
            /\.toml$/,
            "",
          )}」）`,
      )
      .join("\n  ")}\n  处理：确认命令确实已改名 / 删除后，手动删掉这些文件（B-25）`,
  );
}
if (missingFiles.length) {
  fail(
    `权限目录**缺少生成物**（命令在 COMMANDS 里，却没有对应的权限文件）：\n  ${missingFiles
      .map(
        (file) =>
          `${relative(root, join(AUTOGENERATED_DIR, file))}（在 src-tauri/ 跑一次构建会生成它）`,
      )
      .join("\n  ")}`,
  );
}
if (!ghostFiles.length && !missingFiles.length) {
  ok(
    `权限生成物与命令集合一致（${actualPermissionFiles.length} 个文件 == ${rust.length} 条命令）`,
  );
}

// ---------------------------------------------------------------- 5. 通道名对账（B-101）
// 前端 `CHANNELS` 的 id 集合必须与后端 `DeliveryChannel::ALL` 的 `as_str()` 集合相同。
// 少一个 ⇒ 用户选不到新通道；多一个 ⇒ 选到一个后端不认识的通道。
const rustChannels = parseRustChannels();
const tsChannels = parseTsChannels();
const onlyBackend = rustChannels.filter((c) => !tsChannels.includes(c));
const onlyFrontend = tsChannels.filter((c) => !rustChannels.includes(c));
if (onlyBackend.length || onlyFrontend.length) {
  fail(
    `投递通道名两边不一致（B-101）：\n` +
      (onlyBackend.length
        ? `  只有后端有: ${onlyBackend.join(", ")}\n`
        : "") +
      (onlyFrontend.length
        ? `  只有前端有: ${onlyFrontend.join(", ")}（后端不认识的通道，用户选到了也发不出去）\n`
        : "") +
      `  后端清单来自 delivery/mod.rs 的 as_str()（${rustChannels.length} 条），` +
      `前端清单来自 Agents.tsx 的 CHANNELS（${tsChannels.length} 条）`,
  );
} else {
  ok(`投递通道名两边一致（${rustChannels.length} 条）`);
}

// ------------------------------------------- 5b. AGENT_CHANNELS 对账（M8-S7 / B-116 P2-1）
// `channelOfBinding` 用的第二张前端表。`CHANNELS` 的对账覆盖不到它，
// 而它漏一条的后果是「该通道无法批量改指」且无任何东西会红。
const agentTable = parseTsAgentChannels();
const rustChannelsForAgent = parseRustChannels();
const rustAgentIds = parseRustAgentIds();

// ① channel id 集合：AGENT_CHANNELS ∪ CHANNELS == 后端 as_str()
const agentOnly = agentTable.ids.filter((c) => !rustChannelsForAgent.includes(c));
const missingFromAgent = rustChannelsForAgent.filter((c) => !agentTable.ids.includes(c));
if (agentOnly.length || missingFromAgent.length) {
  fail(
    `AGENT_CHANNELS 与后端通道名不一致（M8-S7 / B-116）：\n` +
      (missingFromAgent.length
        ? `  后端有、表里没有: ${missingFromAgent.join(", ")}（这些通道无法批量改指）\n`
        : "") +
      (agentOnly.length
        ? `  只有表里有: ${agentOnly.join(", ")}（后端不认识的通道）\n`
        : "") +
      `  表在 src/lib/api.ts 的 AGENT_CHANNELS`,
  );
}

// ② agent 键集合 == 后端 agent_id() 的臂
const agentKeyOnly = agentTable.keys.filter((a) => !rustAgentIds.includes(a));
const agentIdMissing = rustAgentIds.filter((a) => !agentTable.keys.includes(a));
if (agentKeyOnly.length || agentIdMissing.length) {
  fail(
    `AGENT_CHANNELS 的 agent 键与后端 agent_id() 不一致：\n` +
      (agentIdMissing.length
        ? `  后端有、表里没有: ${agentIdMissing.join(", ")}（这些 agent 的绑定查不到通道）\n`
        : "") +
      (agentKeyOnly.length
        ? `  只有表里有: ${agentKeyOnly.join(", ")}\n`
        : ""),
  );
}

// ③ 两侧表各自的 id 集合必须相同（防「两边都漏同一条」互相掩护）
const frontOnlyAgent = agentTable.ids.filter((c) => !tsChannels.includes(c));
const frontOnlyChannels = tsChannels.filter((c) => !agentTable.ids.includes(c));
if (frontOnlyAgent.length || frontOnlyChannels.length) {
  fail(
    `前端两张表的 channel id 不一致（CHANNELS vs AGENT_CHANNELS）：\n` +
      (frontOnlyChannels.length ? `  只有 CHANNELS 有: ${frontOnlyChannels.join(", ")}\n` : "") +
      (frontOnlyAgent.length ? `  只有 AGENT_CHANNELS 有: ${frontOnlyAgent.join(", ")}\n` : ""),
  );
} else {
  // P3-17 / DEBUG-REPORT-v3 §3-17：文案只说 ③ 自己检查的（前端两张表 id 集合一致），
  // 不提「与后端对账」——那是 ①② 的职责；①② fail 时这里打 ✓ 会变成「先 ✗ 后 ✓」
  // 的误导顺序。
  ok(
    `CHANNELS 与 AGENT_CHANNELS 的 channel id 集合一致（${agentTable.ids.length} 条 / ${agentTable.keys.length} 个 agent）`,
  );
}

if (process.exitCode) {
  console.error("\n命令一致性检查未通过。");
} else {
  console.log("\n命令一致性检查通过。");
}
